// Command genprotocol renders the browser-side protocol module from the Go
// protocol package, so the page never carries a hand-copied command table.
//
// The M0 probe page and the M1 app both consume the same generated file:
//
//	go run ./cmd/genprotocol            # write every output
//	go run ./cmd/genprotocol -check     # fail if any output is stale
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/SilenWang/rk3588-webflasher/internal/device"
	"github.com/SilenWang/rk3588-webflasher/internal/rockusb"
)

func main() {
	outs := flag.String("outs",
		strings.Join([]string{
			filepath.Join("web", "app", "protocol.js"),
			filepath.Join("web", "probe", "protocol.js"),
		}, ","),
		"comma separated output paths")
	check := flag.Bool("check", false, "verify the files are up to date instead of writing them")
	flag.Parse()

	want, err := render()
	if err != nil {
		fmt.Fprintf(os.Stderr, "genprotocol: %v\n", err)
		os.Exit(1)
	}

	paths := strings.Split(*outs, ",")
	stale := false
	for _, raw := range paths {
		path := strings.TrimSpace(raw)
		if path == "" {
			continue
		}
		if err := sync(path, want, *check); err != nil {
			fmt.Fprintf(os.Stderr, "genprotocol: %v\n", err)
			os.Exit(1)
		}
		if *check {
			got, err := os.ReadFile(path)
			if err != nil || !bytes.Equal(got, want) {
				stale = true
			}
		}
	}
	if *check {
		if stale {
			fmt.Fprintf(os.Stderr, "genprotocol: generated protocol.js is stale; run `pixi run gen`\n")
			os.Exit(1)
		}
		fmt.Println("genprotocol: generated files are up to date")
	}
}

func sync(path string, want []byte, check bool) error {
	got, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	if check {
		return nil
	}
	if bytes.Equal(got, want) {
		fmt.Printf("genprotocol: %s unchanged\n", path)
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(path, want, 0o644); err != nil {
		return err
	}
	fmt.Printf("genprotocol: wrote %s\n", path)
	return nil
}

func render() ([]byte, error) {
	var b strings.Builder

	b.WriteString(`// Code generated by cmd/genprotocol from internal/rockusb and
// internal/device; DO NOT EDIT.
//
// Source of truth: internal/rockusb/protocol.go and downloadboot.go, both
// transcribed from Rockchip's GPL-2.0 rkdeveloptool (RKComm.h / RKComm.cpp /
// RKDevice.h / RKBoot.cpp). Regenerate with ` + "`pixi run gen`" + `.

export const PROTOCOL = "rockusb/M1-wasm";
/** No flash write, erase or reset path exists in this build. */
export const FLASH_WRITES = false;
/** Download Boot writes the loader into maskrom RAM over EP0 vendor requests. */
export const DOWNLOAD_BOOT = true;
`)
	fmt.Fprintf(&b, "export const CORE_VERSION = %s;\n\n", strconv.Quote(device.CoreVersion))

	b.WriteString(`export const CBW_SIGNATURE = 0x43425355; // "USBC"
export const CSW_SIGNATURE = 0x53425355; // "USBS"
export const CBW_LENGTH = 31;
export const CSW_LENGTH = 13;
export const DIRECTION_IN = 0x80;
export const DIRECTION_OUT = 0x00;
export const ROCKCHIP_VENDOR_ID = 0x2207;
export const STATUS_PASSED = 0x00;
export const STATUS_FAILED = 0x01;

`)

	b.WriteString(`/**
 * Download Boot vendor requests (RKComm.cpp RKU_DeviceRequest). The loader is
 * sent as bmRequestType=0x40, bRequest=0x0C control transfers of at most 4096
 * bytes, with a CRC-CCITT (init 0xFFFF, high byte first) appended to each
 * entry's payload.
 */
export const VENDOR = Object.freeze({
  requestType: 0x40,
  request: 0x0c,
  index471: 0x0471,
  index472: 0x0472,
  chunkSize: 4096,
  crcCCITTInit: 0xffff,
  settleMs: 1000,
});
`)

	b.WriteString("export const ERROR_NAMES = {\n")
	codes := []rockusb.ErrorCode{
		rockusb.ErrSuccess,
		rockusb.ErrDeviceOpenFailed,
		rockusb.ErrDeviceWriteFailed,
		rockusb.ErrDeviceReadFailed,
		rockusb.ErrCmdNotMatch,
		rockusb.ErrDeviceUnready,
		rockusb.ErrFailed,
		rockusb.ErrDeviceNotSupport,
		rockusb.ErrRequestFail,
		rockusb.ErrTimeout,
	}
	for _, code := range codes {
		// Negative numbers are not valid bare object keys in JavaScript.
		fmt.Fprintf(&b, "  %s: %s,\n", strconv.Quote(strconv.Itoa(int(code))), strconv.Quote(code.String()))
	}
	b.WriteString("};\n\n")

	b.WriteString(`/**
 * The complete set of commands the tool may issue. Any opcode outside this
 * table is rejected before a transfer is attempted (Go: rockusb.IsReadOnly).
 */
export const COMMANDS = [
`)
	for _, c := range rockusb.Commands {
		fmt.Fprintf(&b, "  { op: 0x%02X, name: %s, transferLength: %d, dataLength: %d, allowShort: %t, description: %s },\n",
			byte(c.Op), strconv.Quote(c.Name), c.TransferLength, c.DataLength, c.AllowShort, strconv.Quote(c.Description))
	}
	b.WriteString("];\n\n")

	b.WriteString("export const COMMANDS_BY_OP = Object.freeze(\n  Object.fromEntries(COMMANDS.map((c) => [c.op, c])),\n);\n\n")

	b.WriteString("export const STORAGE_NAMES = Object.freeze({\n")
	ids := make([]int, 0, 4)
	for id := range storageNames() {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	for _, id := range ids {
		fmt.Fprintf(&b, "  %d: %s,\n", id, strconv.Quote(rockusb.StorageName(id)))
	}
	b.WriteString("});\n\n")

	b.WriteString("export const MANUFACTURER_NAMES = Object.freeze([\n")
	for _, name := range manufacturerNames() {
		fmt.Fprintf(&b, "  %s,\n", strconv.Quote(name))
	}
	b.WriteString("]);\n")

	b.WriteString("\n/** Shell commands, i.e. the CLI surface of the wasm core. */\nexport const SHELL_COMMANDS = Object.freeze([\n")
	for _, c := range device.Commands {
		fmt.Fprintf(&b, "  { name: %s, usage: %s, summary: %s },\n",
			strconv.Quote(c.Name), strconv.Quote(c.Usage), strconv.Quote(c.Summary))
	}
	b.WriteString("]);\n")

	return []byte(b.String()), nil
}

// storageNames is intentionally re-derived through the public API: genprotocol
// only needs the ids, never the internal map.
func storageNames() map[int]string {
	return map[int]string{1: rockusb.StorageName(1), 2: rockusb.StorageName(2), 3: rockusb.StorageName(3), 9: rockusb.StorageName(9)}
}

func manufacturerNames() []string {
	return []string{"SAMSUNG", "TOSHIBA", "HYNIX", "INFINEON", "MICRON", "RENESAS", "ST", "INTEL"}
}
